<template><view class="mg-prep" :style="viewportCss"><button class="back" @click="back">← 返回</button><view class="card"><text class="eyebrow">RehabMotion 康复游戏</text><text class="title">地鼠大作战</text><text class="sub">箱式深蹲 · 双侧同步完成一个动作周期</text><view class="row"><text>训练组数</text><button v-if="editable" @click="change('sets',-1)">−</button><strong>{{config.targetSets}}</strong><button v-if="editable" @click="change('sets',1)">＋</button></view><view class="row"><text>每组目标次数</text><button v-if="editable" @click="change('count',-1)">−</button><strong>{{config.targetCount}}</strong><button v-if="editable" @click="change('count',1)">＋</button></view><view class="row"><text>游戏节奏</text><button v-if="editable" @click="tempo(-500)">−</button><strong>{{(config.warningWindowMs/1000).toFixed(1)}}s</strong><button v-if="editable" @click="tempo(500)">＋</button></view><text class="note">实时使用 motion_progress / motion_stage 驱动地鼠下沉与探出；both_rep_done 仅确认有效动作完成。</text><button class="start" @click="start">开始训练</button></view></view></template>
<script lang="ts">import{configureCallerReturnUrl,appendReturnUrl,returnToCaller}from'../../game-platform/runtime/navigation';import{getViewportLayout,viewportStyle}from'../../game-platform/runtime/viewport';import{configureMoleFromQuery}from'../runtime/launch-config';import{configureMoleSession,getMoleConfig,registerMoleResultEmitter}from'../runtime/session-runtime';export default{name:'MolePrepare',data(){return{config:getMoleConfig(),viewport:getViewportLayout(),multiplayer:false,returning:false}},computed:{editable():boolean{return this.config.sourceKind==='fake'},viewportCss():Record<string,string>{return viewportStyle(this.viewport,'--mg-safe-top')}},onLoad(q:Record<string,string|undefined>){configureCallerReturnUrl(q.returnUrl,'/pages-mole-game/home/index');this.multiplayer=q.multiplayer==='1';this.config=configureMoleFromQuery(q);const ch=(this as any).getOpenerEventChannel?.();registerMoleResultEmitter(r=>ch?.emit('moleGameResult',r))},onResize(){this.viewport=getViewportLayout()},methods:{change(k:string,d:number){this.config=configureMoleSession(k==='sets'?{...this.config,targetSets:this.config.targetSets+d}:{...this.config,targetCount:this.config.targetCount+d})},tempo(d:number){this.config=configureMoleSession({...this.config,warningWindowMs:this.config.warningWindowMs+d})},start(){uni.redirectTo({url:appendReturnUrl(`/pages-mole-game/game/index${this.multiplayer?'?multiplayer=1':''}`)})},back(){if(this.returning)return;this.returning=true;registerMoleResultEmitter(null);returnToCaller()}}}</script>
<style scoped>.mg-prep{position:relative;display:flex;align-items:center;justify-content:center;box-sizing:border-box;width:100vw;height:100vh;overflow:hidden;padding:var(--mg-safe-top,8px) 14px 12px;background:linear-gradient(#8ed9ef 0 45%,#91d64e 45%);font-family:"Microsoft YaHei",sans-serif;color:#385024}.back{position:absolute;z-index:3;top:calc(var(--mg-safe-top,8px) + 6px);left:14px;border:0;border-radius:999px;background:#fff;color:#587a2f}.card{width:min(650px,84vw);padding:18px 24px;border:4px solid #719d35;border-radius:24px;background:rgba(255,255,255,.97);box-shadow:0 9px 0 rgba(74,105,30,.25)}.eyebrow,.title,.sub,.note{display:block;text-align:center}.title{font-size:clamp(32px,7vh,52px);font-weight:900;color:#6e9228}.row{display:flex;align-items:center;justify-content:center;gap:10px;margin:10px 0;padding:8px;border-radius:14px;background:#eff7df}.row text{width:135px}.row button{width:34px;height:34px;margin:0;padding:0;border:0;border-radius:50%;background:#78a93f;color:#fff}.note{font-size:12px;color:#758365}.start{display:flex;align-items:center;justify-content:center;width:300px;height:48px;margin:12px auto 0;border:0;border-radius:999px;background:#f6bd31;color:#594208;font-size:18px;font-weight:900}</style>
